                    <button id="btn-export-csv" style="flex:1;background:rgba(255,255,255,.03);color:#a6adc8;border:1px solid rgba(255,255,255,.06);padding:4px;border-radius:6px;cursor:pointer;font-size:9px;">CSV</button>
